import{_ as l,o,c as i,a2 as e}from"./chunks/framework.1lR7qgqY.js";const h=JSON.parse('{"title":"M0 基礎環境","description":"","frontmatter":{},"headers":[],"relativePath":"build/m0-foundation.md","filePath":"build/m0-foundation.md","lastUpdated":null}'),r={name:"build/m0-foundation.md"};function t(n,a,m,s,u,d){return o(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="m0-基礎環境" tabindex="-1">M0 基礎環境 <a class="header-anchor" href="#m0-基礎環境" aria-label="Permalink to &quot;M0 基礎環境&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 撰寫中 (僅有大綱)</li><li>資料基準日: 2026-10-26</li><li>待查證: Proxmox VE 與 Proxmox Backup Server 的版本與設定步驟待依官方文件驗證</li></ul></div><p><strong>結論</strong>: 後續每個模組都放在這一章準備的環境裡: 一台主機, 一個不對外開放的內網網段, 以及能還原的備份. 單人單機可以只用一台 Linux 或 Mac 加 Docker; 多人共用時, 改用 Proxmox VE 以 VM 劃分信任區.</p><p><strong>這一塊在圖上的位置</strong>: 實體主機 Proxmox VE, 各 VM 區的邊界, 以及備份伺服器. <strong>前置模組</strong>: 無. <strong>完成後的狀態</strong>: 主機, 網段與備份都已就位, 可以開始組裝 M1.</p><h2 id="m0-1-兩種起點-單機或-proxmox-ve" tabindex="-1">M0.1 兩種起點: 單機或 Proxmox VE <a class="header-anchor" href="#m0-1-兩種起點-單機或-proxmox-ve" aria-label="Permalink to &quot;M0.1 兩種起點: 單機或 Proxmox VE&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>單機: Linux 或 macOS 加 Docker, 適合里程碑 1</li><li>Proxmox VE: 以 VM 劃分入口區, 推論區, 閘道區等信任區, 適合里程碑 2 以上</li><li>接觸不可信內容的元件放 VM, 不放 LXC 容器 (隔離較弱)</li></ul><h2 id="m0-2-內網網段與防火牆" tabindex="-1">M0.2 內網網段與防火牆 <a class="header-anchor" href="#m0-2-內網網段與防火牆" aria-label="Permalink to &quot;M0.2 內網網段與防火牆&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>只開放內網, 公網不做任何連接埠轉發</li><li>各 VM 區之間的允許連線清單 (對照組裝總覽的部署分區表)</li><li>管理介面放在獨立的管理網段, 並開啟雙因素驗證</li></ul><h2 id="m0-3-docker-與容器的共同設定" tabindex="-1">M0.3 Docker 與容器的共同設定 <a class="header-anchor" href="#m0-3-docker-與容器的共同設定" aria-label="Permalink to &quot;M0.3 Docker 與容器的共同設定&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>發布連接埠時指定 127.0.0.1 或內部網路</li><li>映像以摘要值鎖定版本 (見 O2)</li><li>機密存在 .env, 權限 600</li></ul><h2 id="m0-4-備份伺服器" tabindex="-1">M0.4 備份伺服器 <a class="header-anchor" href="#m0-4-備份伺服器" aria-label="Permalink to &quot;M0.4 備份伺服器&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>Proxmox Backup Server 或 NAS, 每週備份 VM 與資料卷</li><li>先完成一次還原演練, 再進入 M1 (見 O1)</li></ul><h2 id="m0-5-驗收測試" tabindex="-1">M0.5 驗收測試 <a class="header-anchor" href="#m0-5-驗收測試" aria-label="Permalink to &quot;M0.5 驗收測試&quot;">​</a></h2><p>待撰寫要點:</p><ul><li>從外部網路掃描, 確認沒有開放的連接埠</li><li>還原一台測試 VM, 確認備份可用</li></ul>',19)])])}const p=l(r,[["render",t]]);export{h as __pageData,p as default};
